-- Migration 007 — M1000 CANA full flow: main draw, classification, dependencies, schedule.
-- Generated from official Excel flow spec (Order of play - Thursday, Main Draw, Ranking sheets, Fri/Sat Sched, Qualif.).
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS match_result_bindings (
  id TEXT PRIMARY KEY,
  matchId TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  outcome TEXT NOT NULL CHECK(outcome IN ('WINNER','LOSER')),
  positionMin INTEGER NOT NULL,
  positionMax INTEGER NOT NULL,
  UNIQUE(matchId, outcome)
);

-- 0. CURRENT DATABASE CLEANUP (spec section 37): migration 006 left 10 men
--    qualifying fixtures (Group C, Group D) with a NULL team on one side, and
--    Group C's group_teams roster was missing 2 of its 5 teams (they were only
--    referenced by matches, never registered for standings/qualification).
--    Corrected against the official Group C / Group D fixture list — no new
--    seed records invented, only the missing side of an already-half-correct row filled in.
INSERT OR IGNORE INTO group_teams (groupId,teamId,seedPosition) VALUES ('group-men-group-c','team-men-team-22',2);
INSERT OR IGNORE INTO group_teams (groupId,teamId,seedPosition) VALUES ('group-men-group-c','team-men-team-25',3);
